<script>
(function () {
  // ---- Sample dataset (replace `rows` with tool output) ----
  const columns = [
    { key: "name",    label: "Name",      align: "left"  },
    { key: "email",   label: "Email",     align: "left"  },
    { key: "plan",    label: "Plan",      align: "left"  },
    { key: "mrr",     label: "MRR",       align: "right", type: "currency" },
    { key: "seats",   label: "Seats",     align: "right", type: "number" },
    { key: "status",  label: "Status",    align: "left",  type: "status" },
    { key: "created", label: "Created",   align: "left"  },
  ];

  const rows = [
    { name: "Acme Corp",       email: "ops@acme.io",        plan: "Enterprise", mrr: 4800, seats: 120, status: "active",  created: "2024-11-02" },
    { name: "Bluefin Labs",    email: "hi@bluefin.dev",     plan: "Pro",        mrr: 990,  seats: 24,  status: "active",  created: "2025-01-18" },
    { name: "Corvus Media",    email: "team@corvus.tv",     plan: "Pro",        mrr: 690,  seats: 12,  status: "pending", created: "2025-03-07" },
    { name: "Delta Foods",     email: "it@deltafoods.com",  plan: "Starter",    mrr: 149,  seats: 5,   status: "churned", created: "2024-06-21" },
    { name: "Everline",        email: "admin@everline.co",  plan: "Enterprise", mrr: 6200, seats: 210, status: "active",  created: "2023-09-14" },
    { name: "Foxtrot Inc",     email: "billing@foxtrot.io", plan: "Starter",    mrr: 99,   seats: 3,   status: "pending", created: "2025-05-29" },
    { name: "Grove Analytics", email: "hello@grove.ai",     plan: "Pro",        mrr: 1290, seats: 30,  status: "active",  created: "2024-12-10" },
    { name: "Halcyon",         email: "care@halcyon.app",   plan: "Starter",    mrr: 49,   seats: 2,   status: "churned", created: "2024-02-03" },
  ];

  // ---- State ----
  let sortKey = null;
  let sortDir = 1; // 1 asc, -1 desc

  const $tbody   = document.getElementById("tbody");
  const $headRow = document.getElementById("headRow");
  const $search  = document.getElementById("search");
  const $status  = document.getElementById("statusFilter");
  const $clear   = document.getElementById("clearBtn");
  const $empty   = document.getElementById("empty");
  const $summary = document.getElementById("summary");
  const $footer  = document.getElementById("footer");

  const fmt = {
    currency: (v) => "$" + Number(v).toLocaleString("en-US"),
    number:   (v) => Number(v).toLocaleString("en-US"),
  };

  const statusChip = (s) => {
    const map = {
      active:  "bg-emerald-50 text-emerald-700 ring-emerald-600/20",
      pending: "bg-amber-50 text-amber-700 ring-amber-600/20",
      churned: "bg-rose-50 text-rose-700 ring-rose-600/20",
    };
    const cls = map[s] || "bg-slate-100 text-slate-600 ring-slate-500/20";
    return '<span class="inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium capitalize ring-1 ring-inset ' + cls + '">' + s + '</span>';
  };

  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({
    "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"
  }[c]));

  // ---- Header render ----
  function renderHead() {
    $headRow.innerHTML = columns.map((c) => {
      const alignCls = c.align === "right" ? "text-right" : "text-left";
      const arrow = sortKey === c.key ? (sortDir === 1 ? "▲" : "▼") : "";
      return '<th data-key="' + c.key + '" ' +
        'class="cursor-pointer select-none whitespace-nowrap px-4 py-3 ' + alignCls +
        ' text-xs font-semibold uppercase tracking-wide text-slate-500 hover:text-slate-700">' +
        '<span class="inline-flex items-center gap-1">' + esc(c.label) +
        '<span class="text-[10px] text-indigo-500">' + arrow + '</span></span></th>';
    }).join("");

    $headRow.querySelectorAll("th").forEach((th) => {
      th.addEventListener("click", () => {
        const key = th.dataset.key;
        if (sortKey === key) sortDir *= -1;
        else { sortKey = key; sortDir = 1; }
        renderHead();
        renderBody();
      });
    });
  }

  // ---- Filtering + sorting ----
  function getVisible() {
    const q = $search.value.trim().toLowerCase();
    const st = $status.value;

    let out = rows.filter((r) => {
      if (st && r.status !== st) return false;
      if (!q) return true;
      return columns.some((c) => String(r[c.key]).toLowerCase().includes(q));
    });

    if (sortKey) {
      const col = columns.find((c) => c.key === sortKey);
      out = out.slice().sort((a, b) => {
        let av = a[sortKey], bv = b[sortKey];
        if (col && (col.type === "number" || col.type === "currency")) {
          av = Number(av); bv = Number(bv);
        } else {
          av = String(av).toLowerCase(); bv = String(bv).toLowerCase();
        }
        if (av < bv) return -1 * sortDir;
        if (av > bv) return  1 * sortDir;
        return 0;
      });
    }
    return out;
  }

  // ---- Body render ----
  function renderBody() {
    const data = getVisible();
    $empty.classList.toggle("hidden", data.length !== 0);

    $tbody.innerHTML = data.map((r) => {
      const tds = columns.map((c) => {
        const alignCls = c.align === "right" ? "text-right tabular-nums" : "text-left";
        let cell;
        if (c.type === "status")       cell = statusChip(r[c.key]);
        else if (c.type === "currency")cell = esc(fmt.currency(r[c.key]));
        else if (c.type === "number")  cell = esc(fmt.number(r[c.key]));
        else if (c.key === "name")     cell = '<span class="font-medium text-slate-900">' + esc(r[c.key]) + '</span>';
        else                            cell = esc(r[c.key]);
        return '<td class="whitespace-nowrap px-4 py-3 ' + alignCls + '">' + cell + '</td>';
      }).join("");
      return '<tr class="hover:bg-slate-50">' + tds + '</tr>';
    }).join("");

    $summary.textContent = data.length + " of " + rows.length + " rows shown";
    $footer.textContent = "Click a column header to sort. Data is filtered client-side.";
  }

  // ---- Events ----
  $search.addEventListener("input", renderBody);
  $status.addEventListener("change", renderBody);
  $clear.addEventListener("click", () => {
    $search.value = "";
    $status.value = "";
    sortKey = null; sortDir = 1;
    renderHead();
    renderBody();
  });

  // ---- Init ----
  renderHead();
  renderBody();
})();
</script>
</body>
